CREATE POLICY "audit_log_shared_select_policy" ON "audit_log" AS PERMISSIVE FOR SELECT TO public USING (EXISTS (SELECT 1 FROM account_shares WHERE account_shares.owner_user_id = "audit_log"."user_id" AND account_shares.shared_with_user_id = current_setting('app.current_user_id', true)::uuid AND account_shares.status = 'accepted'));--> statement-breakpoint
CREATE POLICY "audit_log_shared_insert_policy" ON "audit_log" AS PERMISSIVE FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM account_shares WHERE account_shares.owner_user_id = "audit_log"."user_id" AND account_shares.shared_with_user_id = current_setting('app.current_user_id', true)::uuid AND account_shares.status = 'accepted' AND account_shares.permission = 'edit'));